const data = $input.first().json;
const answers = data.form_response?.answers || [];
const definition = data.form_response?.definition?.fields || [];

function getAnswer(titleContains) {
  const field = definition.find(f => f.title?.toLowerCase().includes(titleContains.toLowerCase()));
  if (!field) return 'N/A';
  const answer = answers.find(a => a.field?.id === field.id);
  if (!answer) return 'N/A';
  if (answer.type === 'text') return answer.text || 'N/A';
  if (answer.type === 'number') return answer.number?.toString() || 'N/A';
  if (answer.type === 'boolean') return answer.boolean ? 'Yes' : 'No';
  if (answer.type === 'choice') return answer.choice?.label || 'N/A';
  return 'N/A';
}

const name = getAnswer('name');
const currentWeight = getAnswer('current weight');
const targetWeight = getAnswer('target weight');
const nutritionScore = getAnswer('nutrition adherence');
const nutritionThoughts = getAnswer('nutrition thoughts');
const runningVolume = getAnswer('running volume');
const completedRuns = getAnswer('complete all planned');
const missedReason = getAnswer('missing runs');
const strengthScore = getAnswer('strength training');
const fatigueLevel = getAnswer('fatigue');
const injuries = getAnswer('pain');
const fueling = getAnswer('fueling');
const bestSession = getAnswer('best session');
const focusAreas = getAnswer('focus areas');
const travel = getAnswer('travel');
const supportNeeded = getAnswer('support needed');

const message = `📋 *WEEKLY CHECK-IN*
━━━━━━━━━━━━━━━━━━

👤 *${name}*

⚖️ *Weight*
Current: ${currentWeight} | Target: ${targetWeight}

🍎 *Nutrition*: ${nutritionScore}/10
${nutritionThoughts !== 'N/A' ? `Notes: ${nutritionThoughts}
` : ''}
🏃 *Running*: ${runningVolume} km
Completed all runs: ${completedRuns}
${missedReason !== 'N/A' ? `Missed: ${missedReason}
` : ''}
💪 *Strength*: ${strengthScore}/10

😴 *Fatigue*: ${fatigueLevel}/10

🩹 *Injuries*: ${injuries !== 'N/A' ? injuries : 'None'}

⛽ *Fueling*: ${fueling}

🌟 *Best Session*: ${bestSession !== 'N/A' ? bestSession : '-'}

🎯 *Focus*: ${focusAreas !== 'N/A' ? focusAreas : '-'}

✈️ *Travel*: ${travel !== 'N/A' ? travel : 'None'}

🆘 *Support Needed*: ${supportNeeded !== 'N/A' ? supportNeeded : 'None'}

━━━━━━━━━━━━━━━━━━`;

return [{ json: { message, clientName: name } }];
